node --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync, readFileSync } from 'node:fs';
import { loadVendorFile } from './tools/node-vendor.mjs';
registerHooks({resolve(s,c,n) {
  if (s.endsWith('.js') && s.startsWith('.') && c.parentURL?.includes('/src/')) {
    const t = new URL(s.slice(0,-3)+'.ts',c.parentURL);
    if (existsSync(t)) return n(t.href,c);
  }
  return n(s,c);
}});
for (const p of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js','compiler/typed/typed-rv32.js','compiler/typed/typed-rv32-inline.js','compiler/typed/typed-rv32-loops.js','compiler/typed/typed-rv32-kernel.js']) loadVendorFile(p);
const {setVendor} = await import('./src/typed/vendor.ts');
setVendor({typedTape,typedWasm,typedRv32Interp,typedRv32});
const { Program } = await import('./src/typed/program.ts');
const { storeOf } = await import('./src/typed/ir.ts');
const E = await import('./src/typed/evaluate.ts');
const B = await import('./src/typed/backend/index.ts');
const root = '/home/manuel/code/wesen/2026-10-20--ds-js-os';
const source = ['state','position','moves','search'].map(x=>readFileSync(root+'/apps/typed/chess/'+x+'.typed','utf8')).join('\n');
const p = new Program('chess_probe',source);
console.log(p.status,p.error,p.fns().length);
if (p.status !== 'ok') process.exit(1);
const st = storeOf(p.origin.value);
const ref = typedRv32.compile(source,[],undefined);
const refImage = B.imageFromCode('chess_probe',ref.image,ref.entries);
const image = B.lowerToImage(p.origin).image;
console.log('images',image.value.bytes,ref.image.length);
const host = readFileSync(root+'/bench/host/chess-engine.mjs','utf8');
const board = Function(host.slice(host.indexOf('function board(fen)'),host.indexOf('const square = dense'))+';return board')();
const positions = JSON.parse(readFileSync(root+'/bench/reference/chess/reference-positions.json','utf8')).positions;
for (const f of positions) {
  const cells = [...board(f.fen),...Array(12288-135).fill(0)];
  const row = [f.name];
  for (const [fn,args] of [
    ['chessPerft',{board:{cells},depth:1}],
    ['chessPerft',{board:{cells},depth:2}],
    ['chessStartSearch',{board:{cells},state:{record:{}},depth:2,budget:1,advanced:1}]
  ]) {
    const c = E.benchCase(st,fn,args);
    const e = E.evaluate(st,fn,c.args,c.memory,{limit:2e7});
    const a = B.runImage(image,fn,c.args,c.memory,{limit:2e7});
    const r = B.runImage(refImage,fn,c.args,c.memory,{limit:2e7});
    row.push([e.result,e.steps,a.steps,r.steps,E.agrees(e,a),E.agrees(e,r)]);
  }
  console.log(JSON.stringify(row));
}
NODE
